### ❌ Violation

One component loads users, formats dates, and owns the full UI:

```tsx
// VIOLATION: UserDashboard has three reasons to change —
// data fetching, date formatting, and list rendering.
function UserDashboard() {
  const [users, setUsers] = useState<User[]>([]);

  // ❌ Responsibility 1: fetching / data access
  useEffect(() => {
    fetch("/api/users")
      .then((r) => r.json())
      .then(setUsers);
  }, []);

  return (
    <ul>
      {users.map((u) => (
        <li key={u.id}>
          {/* ❌ Responsibility 2: date formatting mixed into JSX */}
          {/* ❌ Responsibility 3: also owns the list UI */}
          {u.name} — joined {new Date(u.joinedAt).toLocaleDateString()}
        </li>
      ))}
    </ul>
  );
}
```

### ✅ Compliant

Split data access, formatting, and presentation:

```tsx
// ✅ Compliant: only loads users — one reason to change (API / data).
function useUsers() {
  const [users, setUsers] = useState<User[]>([]);
  useEffect(() => {
    fetch("/api/users")
      .then((r) => r.json())
      .then(setUsers);
  }, []);
  return users;
}

// ✅ Compliant: only formats dates — change locale/format here alone.
function formatJoined(iso: string) {
  return new Date(iso).toLocaleDateString();
}

// ✅ Compliant: only renders the list — UI changes stay here.
function UserList({ users }: { users: User[] }) {
  return (
    <ul>
      {users.map((u) => (
        <li key={u.id}>
          {u.name} — joined {formatJoined(u.joinedAt)}
        </li>
      ))}
    </ul>
  );
}

// ✅ Compliant: composes the pieces; no fetch/format/render of its own.
function UserDashboard() {
  const users = useUsers();
  return <UserList users={users} />;
}
```

### ❌ Violation

Adding a new notification type means editing the shared renderer:

```tsx
function Notification({ type, message }: { type: string; message: string }) {
  // VIOLATION: closed for extension — every new type forces edits here.
  // ❌ Adding "info" means opening this function and inserting another branch.
  if (type === "success") return <div className="ok">{message}</div>;
  if (type === "error") return <div className="err">{message}</div>;
  if (type === "warning") return <div className="warn">{message}</div>;
  // ❌ Fallback also lives in the same closed switch-like chain.
  return <div>{message}</div>;
}
```

### ✅ Compliant

Map types to renderers; new variants register without rewriting the host:

```tsx
// ✅ Compliant: each notice carries its own render behavior (extension point).
type Notice = { id: string; message: string; render: () => React.ReactNode };

// ✅ Compliant: variants live in a map — add entries without rewriting the list.
const noticeRenderers = {
  success: (message: string) => <div className="ok">{message}</div>,
  error: (message: string) => <div className="err">{message}</div>,
  warning: (message: string) => <div className="warn">{message}</div>,
} as const;

// ✅ Compliant: closed for modification — never branches on type.
function NotificationList({ notices }: { notices: Notice[] }) {
  return (
    <>
      {notices.map((n) => (
        <Fragment key={n.id}>{n.render()}</Fragment>
      ))}
    </>
  );
}

// ✅ Compliant: extend by adding data, not by editing NotificationList.
const billingNotice: Notice = {
  id: "billing",
  message: "Invoice ready",
  render: () => noticeRenderers.success("Invoice ready"),
};
```

### ❌ Violation

`Price` works for any number, including `0` (free). `SalePrice` looks the same but rejects `0` — so it cannot safely replace `Price`:

```tsx
function Price({ cents }: { cents: number }) {
  return <span>{(cents / 100).toFixed(2)}</span>;
}

// ❌ Breaks the contract: throws for 0, which Price allows.
function SalePrice({ cents }: { cents: number }) {
  if (cents <= 0) throw new Error("sale must be > 0");
  return <span className="sale">{(cents / 100).toFixed(2)}</span>;
}

function Product({
  PriceView,
}: {
  PriceView: React.ComponentType<{ cents: number }>;
}) {
  return <PriceView cents={0} />; // free item
}

<Product PriceView={Price} />;     // OK → "0.00"
<Product PriceView={SalePrice} />; // ❌ throws
```

### ✅ Compliant

Keep the same promise — or use a **different** component when the rules differ:

```tsx
// ✅ Same contract as Price: any number, including 0.
function SalePrice({ cents }: { cents: number }) {
  return <span className="sale">{(cents / 100).toFixed(2)}</span>;
}

// ✅ Or don't plug it in as a Price — use it only for real sale amounts.
function SaleBadge({ cents }: { cents: number }) {
  return <span className="sale">{(cents / 100).toFixed(2)}</span>;
}

<Product PriceView={SalePrice} />; // OK with free items
<SaleBadge cents={499} />;         // OK — separate use case
```

### ❌ Violation

Every consumer must satisfy a fat props object:

```tsx
// VIOLATION: one fat interface forces every caller to know every field.
type MegaCardProps = {
  title: string;
  body: string;
  author: string;       // ❌ unused by CommentPreview
  avatarUrl: string;    // ❌ unused by CommentPreview
  onLike: () => void;   // ❌ unused by CommentPreview
  onShare: () => void;  // ❌ unused by CommentPreview
  onEdit: () => void;   // ❌ unused by CommentPreview
  analyticsId: string;  // ❌ unused by CommentPreview
};

function CommentPreview(props: MegaCardProps) {
  // ❌ Depends on MegaCardProps but only reads title + body.
  return (
    <article>
      <h3>{props.title}</h3>
      <p>{props.body}</p>
    </article>
  );
}
```

### ✅ Compliant

Split interfaces so each component asks only for what it needs:

```tsx
// ✅ Compliant: narrow interfaces — clients depend only on what they use.
type ContentProps = { title: string; body: string };
type AuthorProps = { author: string; avatarUrl: string };
type ActionsProps = {
  onLike: () => void;
  onShare: () => void;
  onEdit: () => void;
};

// ✅ Compliant: CommentPreview only requires ContentProps.
function CommentPreview({ title, body }: ContentProps) {
  return (
    <article>
      <h3>{title}</h3>
      <p>{body}</p>
    </article>
  );
}

// ✅ Compliant: author UI has its own small contract.
function AuthorBadge({ author, avatarUrl }: AuthorProps) {
  return (
    <div>
      <img src={avatarUrl} alt="" />
      <span>{author}</span>
    </div>
  );
}

// ✅ Compliant: actions UI is segregated from content/author props.
function CardActions({ onLike, onShare, onEdit }: ActionsProps) {
  return (
    <>
      <button type="button" onClick={onLike}>Like</button>
      <button type="button" onClick={onShare}>Share</button>
      <button type="button" onClick={onEdit}>Edit</button>
    </>
  );
}
```

### ❌ Violation

The component imports and calls a concrete client directly:

```tsx
// ❌ VIOLATION: UI depends on a concrete Stripe module (hard-wired).
import { stripeClient } from "@/lib/stripeClient";

function CheckoutButton({ cartId }: { cartId: string }) {
  return (
    <button
      type="button"
      // ❌ Cannot swap Stripe for a fake/other provider without editing this file.
      onClick={() => stripeClient.createSession(cartId)}
    >
      Pay now
    </button>
  );
}
```

### ✅ Compliant

Inject the dependency so UI stays testable and swappable:

```tsx
// ✅ Compliant: depend on an abstraction, not stripeClient itself.
type CheckoutApi = {
  createSession: (cartId: string) => Promise<void>;
};

function CheckoutButton({
  cartId,
  checkout, // ✅ injected collaborator
}: {
  cartId: string;
  checkout: CheckoutApi;
}) {
  return (
    <button
      type="button"
      // ✅ Calls the abstraction — works with Stripe, a mock, or anything else.
      onClick={() => void checkout.createSession(cartId)}
    >
      Pay now
    </button>
  );
}

// ✅ Compliant: production wires the concrete Stripe client at the edge.
<CheckoutButton cartId="c_1" checkout={stripeClient} />

// ✅ Compliant: tests inject a fake — no Stripe import required in the UI.
<CheckoutButton
  cartId="c_1"
  checkout={{ createSession: async () => {} }}
/>
```
